const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const rows = XLSX.utils.sheet_to_json(wb.Sheets['Travel']);

const flights = rows.filter(r => r.Type === 'Flight');

// --- All flights by user (confirmed + cancelled) ---
const byUser = {};
flights.forEach(f => {
    if (!byUser[f.User]) byUser[f.User] = [];
    byUser[f.User].push({
        id: f['Booking ID'],
        route: f['Route/Location'],
        status: f.Status,
        amount: f.Amount
    });
});

console.log('========== FLIGHT HISTORY BY USER ==========\n');
for (const [user, bookings] of Object.entries(byUser)) {
    console.log('User:', user);
    bookings.forEach(b => {
        const tag = b.status === 'confirmed' ? '✅' : '❌';
        console.log('  ', tag, b.id, '|', b.route, '|', b.status, '| \$' + b.amount);
    });
    console.log();
}

// --- Identify one-way gaps (confirmed only) ---
console.log('========== ONE-WAY GAP ANALYSIS (Confirmed Only) ==========\n');
for (const [user, bookings] of Object.entries(byUser)) {
    const confirmed = bookings.filter(b => b.status === 'confirmed');
    if (confirmed.length === 0) continue;

    const outbound = [];
    const returns = [];

    confirmed.forEach(b => {
        const parts = b.route.split('→').map(s => s.trim());
        if (parts.length === 2 && parts[0] !== parts[1]) {
            outbound.push({ from: parts[0], to: parts[1], id: b.id });
        }
    });

    // Check if there's a matching return for each outbound
    outbound.forEach(o => {
        const hasReturn = outbound.some(r => r.from === o.to && r.to === o.from && r.id !== o.id);
        if (!hasReturn) {
            console.log('  User:', user);
            console.log('    Outbound:', o.from, '→', o.to, '(' + o.id + ')');
            console.log('    ⚠️  No return flight found!\n');
        }
    });
}

// --- Airport & route frequency ---
console.log('========== ROUTE FREQUENCY (All Bookings) ==========\n');
const routeCount = {};
flights.forEach(f => {
    const r = f['Route/Location'];
    routeCount[r] = (routeCount[r] || 0) + 1;
});
Object.entries(routeCount)
    .sort((a,b) => b[1] - a[1])
    .forEach(([route, count]) => console.log('  ', route, ':', count, 'booking(s)'));

console.log('\n========== AIRPORT FREQUENCY (Departures) ==========\n');
const airportCount = {};
flights.forEach(f => {
    const parts = f['Route/Location'].split('→').map(s => s.trim());
    if (parts[0]) airportCount[parts[0]] = (airportCount[parts[0]] || 0) + 1;
});
Object.entries(airportCount)
    .sort((a,b) => b[1] - a[1])
    .forEach(([ap, count]) => console.log('  ', ap, ':', count, 'departure(s)'));
"

