const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const rows = XLSX.utils.sheet_to_json(wb.Sheets['Travel']);

// Look at ALL bookings (not just flights) for patterns around the BK- prefix bookings
console.log('=== All BK- prefix bookings ===');
rows.filter(r => r['Booking ID'].startsWith('BK-') || r['Booking ID'].startsWith('HR-') || r['Booking ID'].startsWith('CR-'))
    .forEach(r => console.log(JSON.stringify(r)));

console.log('\n=== Price analysis for confirmed flights ===');
const confirmed = rows.filter(r => r.Type === 'Flight' && r.Status === 'confirmed' && r.Amount > 0);
confirmed.forEach(r => console.log(r['Booking ID'], '|', r.User, '|', r['Route/Location'], '| \$' + r.Amount));

console.log('\n=== Average prices by route (all flights) ===');
const routePrices = {};
rows.filter(r => r.Type === 'Flight' && r.Amount > 0).forEach(r => {
    const route = r['Route/Location'];
    if (!routePrices[route]) routePrices[route] = [];
    routePrices[route].push(r.Amount);
});
for (const [route, prices] of Object.entries(routePrices)) {
    const avg = prices.reduce((a,b) => a+b, 0) / prices.length;
    console.log(route, '| avg: \$' + avg.toFixed(0), '| bookings:', prices.length, '| prices:', prices);
}

console.log('\n=== Business class price range estimate ===');
// BK-B70889 is Business class at 1180, BK-CE5BA9 at 540
// These are likely longer-haul or premium routes
console.log('BK-B70889: Business, \$1180');
console.log('BK-CE5BA9: \$540');
console.log('Typical short-haul (LAX-SFO, LAX-LAS) confirmed: \$0-\$129');
console.log('The \$1180 and \$540 prices suggest medium/long-haul routes');
"

